const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([125.93, -20.59]);
  const region = point.buffer(1000); // 1km buffer for regional analysis

  // Convert local times to UTC (AWST = UTC+8)
  const dateStr = '2020-01-14';
  const time1Start = ee.Date(dateStr + 'T03:00:00'); // 11:00 AWST = 03:00 UTC
  const time1End = ee.Date(dateStr + 'T03:30:00');
  const time2Start = ee.Date(dateStr + 'T06:00:00'); // 14:00 AWST = 06:00 UTC
  const time2End = ee.Date(dateStr + 'T06:30:00');

  // 2. Data Acquisition - GOES-17 for cloud monitoring
  const goesCol = ee.ImageCollection('NOAA/GOES/17/MCMIPF')
    .filterBounds(region);

  const col1 = goesCol.filterDate(time1Start, time1End);
  const col2 = goesCol.filterDate(time2Start, time2End);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`11:00 AWST Images: ${size1}`);
  console.log(`14:00 AWST Images: ${size2}`);

  // Check for empty collections
  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get first image from each collection (closest to target time)
  const img1 = ee.Image(col1.first());
  const img2 = ee.Image(col2.first());

  // 3. Processing - Use BCM (Binary Cloud Mask) band
  const bcm1 = img1.select('BCM');
  const bcm2 = img2.select('BCM');

  // Count valid pixels
  const stats1 = bcm1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 2000,
    maxPixels: 1e9
  });
  const stats2 = bcm2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 2000,
    maxPixels: 1e9
  });

  const count1 = stats1.get('BCM').getInfo();
  const count2 = stats2.get('BCM').getInfo();

  console.log(`11:00 Valid Pixels: ${count1}`);
  console.log(`14:00 Valid Pixels: ${count2}`);

  // Check for no valid pixels
  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Mean cloud cover (BCM: 0=clear, 1=cloudy)
  const mean1 = bcm1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 2000,
    maxPixels: 1e9
  }).get('BCM').getInfo();

  const mean2 = bcm2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 2000,
    maxPixels: 1e9
  }).get('BCM').getInfo();

  console.log(`11:00 Cloud Cover: ${(mean1 * 100).toFixed(1)}%`);
  console.log(`14:00 Cloud Cover: ${(mean2 * 100).toFixed(1)}%`);
  console.log(`Difference: ${((mean2 - mean1) * 100).toFixed(1)}%`);

  // 5. Validation & Final Answer
  if (mean1 === null || mean2 === null || 
      mean1 < 0 || mean1 > 1 || mean2 < 0 || mean2 > 1) {
    console.log("<answer>C3</answer>");
  } else if (mean2 > mean1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
